    mini: [
      { rows: ['bbbb', 'brgb', 'bbbb'], ink: { b: 0x8a5a3a, r: 0xe06b6b, g: 0x7cc576 } },
      { rows: ['yyy', '.k.', 'kkk'], ink: { y: 0xffe9a0, k: 0x8a8a9a } },
