  },
  sweetie: {
    big: [
      { rows: ['p.p', 'ppp', '.g.', 'gg.', '.g.'], ink: { p: 0xff87af, g: 0x7cc576 } },
      { rows: ['gg.gg', 'gpgpg', 'ggggg', '.ggg.'], ink: { g: 0x6fbf6f, p: 0xff87af } },
      { rows: ['.p.', 'pyp', '.p.', 'ttt', '.t.'], ink: { p: 0xffafd7, y: 0xffe36e, t: 0xd0805a } },
      { rows: ['p.p', '.k.', 'p.p'], ink: { p: 0xffafd7, k: 0x5f4b4b }, lift: 6 },
