      { rows: ['kkkk', 'kuuk', 'kuuk', 'kkkk', 'krbk', 'kkkk'], ink: { k: 0x6a5aa8, u: 0x7fe0ff, r: 0xff6b8a, b: 0xffd447 } },
      { rows: ['yyyyy', '.yyy.', '..y..', '.yyy.'], ink: { y: 0xffd447 } },
      { rows: ['.y.', 'yYy', '.y.'], ink: { y: 0xffd447, Y: 0xfff3b0 }, lift: 5 },
